mapper.select:
SELECT COUNT(*) FROM `tb_user_role` t WHERE t.`is_deleted` = 0
AND t.`user_id` = #{userId}
AND t.`role_id` = #{roleId}
AND EXISTS( SELECT 1 FROM `tb_role` p WHERE t.`role_id` = p.`id` AND p.`is_deleted` = 0 AND p.`status` = 'E' AND p.`code` = #{code})
AND EXISTS( SELECT 1 FROM `tb_role` p WHERE t.`role_id` = p.`id` AND p.`is_deleted` = 0 AND p.`status` = 'E' AND p.`code` IN #{code} )

SELECT COUNT(*)
  FROM `tb_user` t
 WHERE t.`is_deleted` = 0
   AND t.`corp_id` = #{corpId}

	AND t.`is_enabled` = #{enabled}


	   AND EXISTS(


	   AND NOT EXISTS(

	SELECT 1
	  FROM `tb_user_role` p, `tb_role` q
	 WHERE t.`id` = p.`user_id`
	   AND q.`id` = p.`role_id`
	   AND p.`is_deleted` = 0
	   AND q.`is_deleted` = 0

	AND p.`role_id` = #{roleId}


	AND q.`code` IN
	#{code}

)

	AND t.`name` LIKE #{name,typeHandler=com.example.demo.framework.mybatis.type.WildcardTypeHandler}


	AND t.`mobile` LIKE #{mobile,typeHandler=com.example.demo.framework.mybatis.type.WildcardTypeHandler}

SELECT t.`id`, t.`name`, t.`nickname`, t.`mobile`, t.`email`, t.`status`, t.`create_time` AS createTime FROM `tb_user` t WHERE t.`is_deleted` = 0 AND t.`corp_id` = #{corpId}
AND t.`is_enabled` = #{enabled}
AND EXISTS(
AND NOT EXISTS(
SELECT 1 FROM `tb_user_role` p, `tb_role` q WHERE t.`id` = p.`user_id` AND q.`id` = p.`role_id` AND p.`is_deleted` = 0 AND q.`is_deleted` = 0
AND p.`role_id` = #{roleId}
AND q.`code` IN #{code}
)
AND t.`name` LIKE #{name,typeHandler=com.example.demo.framework.mybatis.type.WildcardTypeHandler}
AND t.`mobile` LIKE #{mobile,typeHandler=com.example.demo.framework.mybatis.type.WildcardTypeHandler}
ORDER BY t.`id` DESC LIMIT #{offset}, #{pageSize}
